package main

import "fmt"

type Queue struct {
	items []string
}

func (q *Queue) Enqueue(item string) {
	q.items = append(q.items, item)
}

func (q *Queue) Dequeue() string {
	if q.IsEmpty() {
		return ""
	}
	item := q.items[0]
	q.items = q.items[1:]
	return item
}

func (q *Queue) Front() string {
	if q.IsEmpty() {
		return ""
	}
	return q.items[0]
}

func (q *Queue) IsEmpty() bool {
	return len(q.items) == 0
}

func (q *Queue) Size() int {
	return len(q.items)
}

func main() {
	queue := &Queue{}
	queue.Enqueue("客户A")
	queue.Enqueue("客户B")
	queue.Enqueue("客户C")

	fmt.Println("队首:", queue.Front())
	fmt.Println("服务:", queue.Dequeue())
	fmt.Println("队列大小:", queue.Size())
}
